(function(){
'use strict';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
window.HISTORY_MODE='samples';
const admin=()=>Boolean(authUser);
const api=(path,body,method='POST')=>AuthAPI(path,body,method);
function codeDialog(code){openModal('<h2>Save recovery code</h2><p>Shown once. Keep it private. The previous code is invalid.</p><textarea readonly style="width:100%;min-height:90px" id="generatedCode"></textarea><button class="btn primary closeBtn">I saved it</button>');document.getElementById('generatedCode').value=code;}
window.showRecoveryCode=codeDialog;
devicesPage=function(){return `${head('Connected sensors','Device Management','Connected devices and installation labels are saved with your ThingsBoard account and restored after login. Disconnect keeps the cloud device and its telemetry.',`<button class="btn primary" id="addDevice">Connect / create device</button>`)}<div class="device-grid">${devices.map(d=>`<article class="card device"><div class="device-top"><div><h3>${esc(d.name)}</h3><span class="device-id">${esc(d.id)}</span></div><div class="status ${d.online===true?'':'offline'}"><span class="dot"></span>${d.online==null?'Unknown':d.online?'Online':'Offline'}</div></div><div class="device-meta"><div><small>Location</small>${esc(d.location||'Not set')}</div><div><small>Last updated</small>${esc(d.updated||'Not loaded')}</div></div><div class="device-actions"><button class="btn" data-select-device="${esc(d.id)}">View Data</button><button class="btn" data-edit-device="${esc(d.id)}" >Edit</button><button class="btn danger" data-delete-device="${esc(d.id)}" >Disconnect</button></div></article>`).join('')}</div>${devices.length?'':'<section class="card empty"><strong>No connected devices</strong><p>Connect a device to start viewing its data.</p></section>'}`};
deviceModal=function(d){openModal(`<form id="managedDeviceForm"><h2>${d?'Edit device labels':'Connect a device'}</h2><p>Enter an existing ThingsBoard UUID. Leave ID blank to create a new cloud device.</p><div class="form-grid"><label>Device ID<input class="input" name="id" value="${esc(d?.id||'')}" ${d?'readonly':''}></label><label>Name<input class="input" name="name" required maxlength="120" value="${esc(d?.name||'')}"></label><label>Installation location<input class="input" name="location" maxlength="200" value="${esc(d?.location||'')}"></label><p class="help" id="deviceError"></p><button class="btn primary">${d?'Save labels':'Connect / create'}</button><button type="button" class="btn closeBtn">Cancel</button></div></form>`);const form=document.getElementById('managedDeviceForm');form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;try{await api('/api/thingsboard/devices'+(d?'/'+d.id:''),{id:form.elements.id.value.trim(),name:form.elements.name.value.trim(),location:form.elements.location.value.trim()},d?'PATCH':'POST');closeModal();await refreshThingsBoard();render('devices');toast('Device connection saved in ThingsBoard.')}catch(error){document.getElementById('deviceError').textContent=error.message}finally{button.disabled=false}}};
deleteDeviceModal=function(d){if(!d)return;openModal(`<h2>Disconnect ${esc(d.name)}?</h2><p>This removes this website connection and user assignments. The physical device and ThingsBoard telemetry are retained.</p><button class="btn danger" id="confirmDeleteDevice">Disconnect</button><button class="btn closeBtn">Cancel</button>`);document.getElementById('confirmDeleteDevice').onclick=()=>removeDevice(d)};
removeDevice=async function(d){const button=document.getElementById('confirmDeleteDevice');button.disabled=true;try{await api('/api/thingsboard/devices/'+d.id,undefined,'DELETE');closeModal();if(selectedDevice?.id===d.id){selectedDevice=null;liveSnapshot=null}await refreshThingsBoard();render('devices');toast('Disconnected from website. Cloud data retained.')}catch(error){toast(error.message);button.disabled=false}};
settings=function(){return `${head('Device configuration','Alert Settings','Set the noise threshold for this device.')}<form class="settings" id="settingsForm" novalidate><section class="card settings-card"><label>Device<select class="select" id="settingsDevice">${devices.map(d=>`<option value="${esc(d.id)}" ${selectedDevice?.id===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><div class="form-grid"><label>Threshold (dB)<input class="input" id="threshold" type="number" min="0" max="140" step="0.1" required></label><p id="settingsStatus" hidden role="status" aria-live="polite" style="font-weight:700;white-space:normal;padding:14px;border-radius:10px;background:#eef6f3"></p><button class="btn primary" id="saveConfiguration" type="button" disabled>Save to ThingsBoard</button></div></section><div class="footer-save"></div></form>`};
async function bindSettings(){
 const form=document.getElementById('settingsForm'),select=document.getElementById('settingsDevice'),message=document.getElementById('settingsStatus');if(!form||!select)return;
 const button=document.getElementById('saveConfiguration'),id=select.value,report=text=>{message.textContent=text;message.hidden=false;toast(text)};
 if(!id){report('No assigned devices');return}
 select.onchange=()=>{selectedDevice=devices.find(d=>d.id===select.value);render('settings')};form.querySelectorAll('input').forEach(input=>input.disabled=!admin());
 try{const data=await api('/api/thingsboard/settings?deviceId='+id,undefined,'GET');if(!form.isConnected)return;document.getElementById('threshold').value=data.noise_limit??(liveSnapshot?.current?.deviceId===id?liveSnapshot?.threshold:'')??'';message.textContent='';message.hidden=true;button.disabled=!admin();if(!admin())report('Read-only viewer: only an administrator can save settings.')}catch(error){report(error.message)}
 const save=async event=>{event.preventDefault();if(!form.checkValidity()){report('Enter a valid threshold from 0 to 140 dB.');return}
  button.disabled=true;button.textContent='Saving...';message.hidden=true;
  try{await api('/api/thingsboard/settings?deviceId='+id,{noise_limit:Number(document.getElementById('threshold').value)},'PUT');message.textContent='';message.hidden=true;toast('Saved noise_limit to ThingsBoard Shared attributes.')}catch(error){report(error.message)}finally{button.disabled=false;button.textContent='Save to ThingsBoard'}
 };button.onclick=save;form.onsubmit=save;
}
function addAccountTools(){const root=document.getElementById('content');const note=root.querySelector('.account-local-note');if(note)note.textContent='Profile and password changes are stored on the server.';const section=document.createElement('section');section.className='card settings-card';section.innerHTML='<h2>Account recovery</h2><p>Use a private recovery code to reset your password on the login page. Creating a new code invalidates the old one.</p><form id="recoveryForm"><label>Current password<input class="input" name="password" type="password" autocomplete="current-password" required></label><button class="btn" style="margin-top:12px">Generate recovery code</button><p role="status" id="recoveryMessage"></p></form>';root.append(section);if(authUser?.authProvider==='thingsboard'){section.querySelector('p').textContent='Cloud passwords are managed by ThingsBoard. Change your password above or use a ThingsBoard-issued reset token on the reset page. Legacy NAS recovery codes remain preserved for the local provider.';section.querySelectorAll('input,button').forEach(control=>control.disabled=true);return;}section.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;try{const data=await api('/api/auth/recovery-code',{currentPassword:form.elements.password.value});form.reset();codeDialog(data.recoveryCode)}catch(error){document.getElementById('recoveryMessage').textContent=error.message}finally{button.disabled=false}};}
function formatEventPage(page){if(page==='events'){const intro=document.querySelector('#content .page-head p:not(.eyebrow)');if(intro)intro.textContent='Recorded sound history from ThingsBoard, including normal readings.'}}
const originalRender=window.render;window.render=function(...args){const result=originalRender.apply(this,args),page=document.getElementById('content')?.dataset.page;if(page==='settings')bindSettings();if(page==='account')addAccountTools();formatEventPage(page);if(page==='insights'){const intro=document.querySelector('#content .page-head p:not(.eyebrow)');if(intro)intro.textContent='Continuous sounds count as one event. A new alert starts after the level falls below the limit and rises again.';}if(page==='devices')document.querySelectorAll('[data-select-device]').forEach(button=>button.onclick=async()=>{selectedDevice=devices.find(d=>d.id===button.dataset.selectDevice);liveSnapshot=null;displayedReading='';await refreshThingsBoard();location.hash='dashboard';render('dashboard')});return result;};
// The initial authentication check may still be pending when this file loads.
let lastRole=authUser?.role;const originalUpdate=window.updateAuthButton;window.updateAuthButton=function(...args){const result=originalUpdate.apply(this,args);const role=authUser?.role;if(role!==lastRole){lastRole=role;queueMicrotask(()=>render(location.hash.slice(1)||'dashboard'))}return result;};
if(!document.body.classList.contains('auth-pending'))render();
})();
